import type { QuestionItem } from './konkorData';
import { EXAM_ARCHIVE_IMPORTED_QUESTIONS } from './examArchiveImported';

export type KonkorCourseSectionId =
  | 'english'
  | 'islamic'
  | 'math_stats'
  | 'management_theories'
  | 'economics'
  | 'public_finance'
  | 'human_resources'
  | 'operations_research'
  | 'financial_management'
  | 'production'
  | 'marketing'
  | 'investment_risk'
  | 'entrepreneurship'
  | 'accounting'
  | 'transportation'
  | 'business_transportation';

export interface BookletSubjectRange {
  sectionId: KonkorCourseSectionId;
  title: string;
  fromQuestion: number;
  toQuestion: number;
  count: number;
  coeffBusiness: number;
  coeffIndustrial: number;
  coeffTechnology: number;
  /** Official subject identity from exam-model.v1.json; this is not a knowledge-node mapping. */
  subjectNumber?: number;
  subjectModelId?: string;
  /** Evidence locator for the actual exam booklet cover. */
  sourcePage?: number;
  /** Legacy three-track coefficients are not yet reconciled with the 1405 handbook matrix. */
  coefficientsVerified?: boolean;
}

export interface YearlyKonkorBooklet {
  year: number;
  bookletCode: string;
  examDateLabel: string;
  totalQuestionsInBooklet: number;
  durationMinutes: number;
  pdfAssetUrl: string;
  description: string;
  subjectRanges: BookletSubjectRange[];
}

export interface YearlyKonkorQuestion extends QuestionItem {
  bookletQuestionNumber: number;
  courseSectionId: KonkorCourseSectionId;
  courseSectionTitle: string;
  designedFromTextbook: string;
  examLevel?: 'ارشد' | 'دکتری';
}

