    text: `READING PASSAGE: Humans persistently fail to live up to the ideal of rationality. We make common errors in our decision-making processes and are easily influenced by irrelevant details. And when we rush to a decision without reasoning through all the evidence, we call this trusting our intuition. We used to think the absence of such human quirks made computers better, but recent research in cognitive science tells us otherwise. Humans appear to have two complementary decision-making processes, one slow, deliberate and mostly rational, the other fast, impulsive, and able to match the present situation to prior experience, enabling us to reach a quick conclusion. This latter mode seems to be key to making human intelligence so effective.  While it is deliberative and sound, the rational part requires more time and energy. Imagine that an oncoming car starts to drift into your lane; you need to act immediately: sound the horn, hit the brakes, or swerve, rather than start a lengthy computation that would determine the optimal but possibly belated act. Such shortcuts are also beneficial when there is no emergency. Expend too much brain power computing the optimal solution to details like whether to wear the dark blue or the midnight blue shirt, and you'll quickly run out of time and energy for the important decisions.  So should Artificial Intelligence (AI) incorporate an intuitive component? Indeed, many modern AI systems do have two parts, one that reacts instantly to the situation, and one that does more deliberative reasoning. Some robots, equipped with computers, have an intuitive component built with a "subsumption" architecture, in which the lowest layers of the system are purely reactive, and higher levels serve to inhibit the reactions and organize more goal-directed behavior. This approach has proved to be useful, for example, for getting a legged robot to walk through rough terrain, to name one particularly fascinating and promising development.  QUESTION: The word “persistently” in paragraph 1 is closest in meaning to ................. seeceee8`,
    options: [`deliberately`, `occasionally`, `unfortunately`, `continuously`],
    expectedTimeMs: 60000,
