    text: `READING PASSAGE: Many people like to link the history of social media to the growth in communications technology that has been occurring since the end of the 19th century. A common starting point is Samuel Morse's first telegram, which he sent in 1844 between Washington, D.C. and Baltimore by telegraph. However, this type of communication does not qualify as social media. First, it did not take place "online," and second, telegrams do not contribute to any larger community or collective. Instead, they are used to send individual messages between two people. Therefore, the real history of social media starts in the 1970s with the development of the internet.  The internet has its roots in the 1960s and 1970s when various private and public organizations were working to try and find ways to get computers to communicate with one another. In a sense, this can be considered as the beginning of social media. However, it wasn't until the 1980s, and really the 1990s, that personal computers became more normal, which set the stage for the emergence of social media.  The website credited as being the "first online social media" site is Six Degrees. It's named after the "six degrees of separation" theory, which states that everyone in the world is connected to everyone else by no more than six degrees of separation. The reason Six Degrees is considered to be the first of the social networks is because it allowed people to sign up with their email address, make individual profiles, and add friends to their personal network. It was officially launched in 1997, and it lasted until about 2001. Its number of users peaked at around 3.5 million. It was bought out by YouthStream Media Networks in 1999 for $125 million, but it shut down just about one year later.  QUESTION: The underlined word “it” in paragraph 1 refers to .................`,
    options: [`place`, `social media`, `larger community`, `this type of communication`],
    expectedTimeMs: 60000,
