    sourceReference: 'کنکور دکتری (نیمه‌متمرکز) ۱۴۰۴ — دفترچهٔ زبان عمومی، سؤال ۳۵؛ کلید رسمی منتشرشده در «پاسخ کلیدی دفترچه زبان عمومی کنکور دکتری ۱۴۰۴»',
    text: `READING PASSAGE: Many people like to link the history of social media to the growth in communications technology that has been occurring since the end of the 19th century. A common starting point is Samuel Morse's first telegram, which he sent in 1844 between Washington, D.C. and Baltimore by telegraph. However, this type of communication does not qualify as social media. First, it did not take place "online," and second, telegrams do not contribute to any larger community or collective. Instead, they are used to send individual messages between two people. Therefore, the real history of social media starts in the 1970s with the development of the internet.  The internet has its roots in the 1960s and 1970s when various private and public organizations were working to try and find ways to get computers to communicate with one another. In a sense, this can be considered as the beginning of social media. However, it wasn't until the 1980s, and really the 1990s, that personal computers became more normal, which set the stage for the emergence of social media.  The website credited as being the "first online social media" site is Six Degrees. It's named after the "six degrees of separation" theory, which states that everyone in the world is connected to everyone else by no more than six degrees of separation. The reason Six Degrees is considered to be the first of the social networks is because it allowed people to sign up with their email address, make individual profiles, and add friends to their personal network. It was officially launched in 1997, and it lasted until about 2001. Its number of users peaked at around 3.5 million. It was bought out by YouthStream Media Networks in 1999 for $125 million, but it shut down just about one year later.  QUESTION: According to the passage, which of the following statements is true?`,
    options: [`The scholar famous for his theory of “six degrees of separation” actually chose a name for the first social media website.`, `The first telegram was transferred between Washington, D.C. and Baltimore approximately in the mid-18th century.`, `Until the 1980s, when personal computers became more widely accessible, it was merely the governmental sector that utilized computers for the purpose of communication.`, `The first social media website was launched in the 1990s, only to shut down less than half a decade later, roughly one year following its acquisition by another company. Historians don’t know for certain if the first prosthetics were primarily functional or for appearances. According to Katherine Ott, Ph.D., curator for the Division of Medicine and Science at the Smithsonian Institution’s National Museum of American History, this is partly because different cultures have their own ideas about what makes a person whole. The oldest known prosthetics are two different artificial toes from ancient Egypt. One prosthetic toe, known as the “Greville Chester toe,” was made from cartonnage, which is a kind of papier-maché made from glue, linen, and plaster. It is thought to be between 2,600 and 3,400 years old, though its exact age is unknown. Because it doesn’t bend, researchers believe it was cosmetic. The other prosthetic, a wooden and leather toe known as the “Cairo toe,” is estimated to be between 2,700 and 3,000 years old. It is thought to be the earliest known practical artificial limb due to its flexibility and because it was refitted for the wearer multiple times. Approximately 300 years later—300 B.C.—in Italy, an ancient Roman nobleman used a prosthetic leg known as the “Capua leg.” The leg was made of bronze and hollowed-out wood and was held up with leather straps. Other known early prosthetics include artificial feet from Switzerland and Germany, crafted between the 5th and 8th centuries. These were made from wood, iron, or bronze and may have been strapped to the amputee’s remaining limb. Soldiers who lost their limbs in battle often used early artificial limbs made of wood or iron. For instance, about 2,200 years ago, the Roman general Marcus Sergius Silus lost his right hand during the Second Punic War. He had it replaced with an iron one that was designed to hold his shield. Knights of the Middle Ages sometimes used wooden limbs for battle or to ride a horse. And in the 16th century, the reputable French surgeon Ambroise Paré designed and developed some of the first purely functional prosthetics for soldiers coming off the battlefield. He also published the earliest written reference to prosthetics in one of his detailed expositions about his ground-breaking discoveries on the subject.`],
    expectedTimeMs: 60000,
