    text: `READING PASSAGE: A very fundamental factor in the supervision of Ph.D. students is the supervisor's availability, where availability does not only refer to frequent physical presence, but also to having frequent meetings with the Ph.D. student, and providing timely answers to questions via email and feedback on the student's written work. Several studies show that Ph.D. students attach great value to their supervisors' availability, e.g. timely feedback, timely responses to questions, and frequent meetings. Moreover, some studies reported that there is a relationship between frequent supervision and a lower attrition risk. In addition to the quality of supervision (support and relationship), quantity thus also seems to matter.  An aspect related to Ph.D. supervision that—to our knowledge—has not been quantitatively investigated as a factor that could be related to Ph.D. students' success is the level of expectation the supervisor holds regarding their achievement. Previous qualitative research shows that Ph.D. supervisors expect high levels of commitment and independence from their Ph.D. students. Circumstantial evidence also reveals that a few supervisors occasionally seem to expect a lot from their Ph.D. students; for instance, that they all publish papers based on their Ph.D. dissertation, and only publish them in high-impact journals, and build international networks, among other things. Although this may be achievable for some Ph.D. students, for the vast majority it is probably not. Such high expectations can result in dissatisfaction or cause the Ph.D. student to miss the deadlines or even consider quitting.  QUESTION: The underlined word “fundamental” in paragraph 1 is closest in meaning to .................`,
