    text: `READING PASSAGE: In just its first year of scientific operations, the $10-billion infrared telescope has delivered stunning views of the nascent universe, finding large numbers of surprisingly bright galaxies that existed at a time when the cosmos was in its infancy. With its 6.5-meter mirror, the James Webb Space Telescope (JWST) was designed to investigate this early era, which was mostly out of reach for its predecessor, the 2.4-meter Hubble Space Telescope (HST). [1] Observations thus far have astonished researchers and left them trying to digest exactly what they are seeing. According to the standard model of cosmology, after the fiery Big Bang 13.8 billion years ago, the universe cooled, and energy turned into matter that eventually coalesced during the first few hundred million years, forming the first generation of stars and galaxies. [2]  But JWST's initial results may suggest that stars and galaxies were forming far faster than anyone expected. The telescope had done nothing less, read the headlines, than "break the universe" and upend models of cosmic history. [3] Subsequent data have ruled out some of the more dramatic findings, and new simulations can accommodate at least a few of the strange observations. But some bright, massive, and early galaxies continue to confound theorists, suggesting that our understanding could shift in the coming years. "No data at the moment has broken the universe," says Priyamvada Natarajan, a theoretical astrophysicist at Yale University in New Haven. [4] "But I think there are interesting potential tensions emerging on different scales." Resolving these tensions will require researchers to revisit their deep-seated assumptions about galactic evolution. That could mean bringing some ideas to the forefront—while leaving others in the cosmic dustbin.  QUESTION: According to paragraph 2, which of the following is true about JWST?`,
